        let Some(session) = self.active() else {
            return false;
        };
        if !session.busy() || !session.alive().await {
            return false;
        }
        let steered = match session.steer(text).await {
            Ok(()) => true,
            Err(error) => {
                tracing::info!(route = %self.route, %error, "could not steer; queueing the utterance");
